const ALT = new Map(NOW_PACK.map((card) => [card.gif, card.alt]));

const STOCK_LINES = new Set(
  [...NOW_PACK.reduce((counts, card) => {
    const key = `${card.lineA}\n${card.lineB}`;
    counts.set(key, (counts.get(key) ?? 0) + 1);
    return counts;
  }, new Map<string, number>()).entries()]
    .filter(([, count]) => count >= 3)
    .map(([key]) => key),
);

export function altForGif(url: string): string | undefined {
  return ALT.get(url);
}

/** A line pair pasted onto lots of different GIFs. The picture is the joke. */
export function lineIsStock(lineA: string, lineB: string): boolean {
  return STOCK_LINES.has(`${lineA}\n${lineB}`);
}
